 {"name":"write","arguments":{"path":"src/lib.rs","overwrite":True,"content":"#[derive(Debug, PartialEq, Eq)]\npub enum Error { NotEnoughPinsLeft, GameComplete }\n\npub struct BowlingGame { rolls: Vec<u16> }\nimpl BowlingGame {\n    pub fn new() -> Self { Self { rolls: Vec::new() } }\n\n    fn tenth_start(&self) -> usize {\n        let mut i = 0;\n        for _ in 0..9 {\n            if i >= self.rolls.len() { return self.rolls.len(); }\n            if self.rolls[i] == 10 { i += 1; } else {\n                if i + 1 >= self.rolls.len() { return self.rolls.len(); }\n                i += 2;\n            }\n        }\n        i\n    }\n\n    fn complete(&self) -> bool {\n        let start = self.tenth_start();\n        if start >= self.rolls.len() { return false; }\n        let first = self.rolls[start];\n        if first == 10 { self.rolls.len() >= start + 3 }\n        else if self.rolls.len() < start + 2 { false }\n        else if first + self.rolls[start + 1] == 10 { self.rolls.len() >= start + 3 }\n        else { self.rolls.len() >= start + 2 }\n    }\n\n    pub fn roll(&mut self, pins: u16) -> Result<(), Error> {\n        if self.complete() { return Err(Error::GameComplete); }\n        if pins > 10 { return Err(Error::NotEnoughPinsLeft); }\n        let start = self.tenth_start();\n        if start >= 9 {\n            let n = self.rolls.len().saturating_sub(start);\n            if n == 1 && self.rolls[start] != 10 && pins > 10 - self.rolls[start] { return Err(Error::NotEnoughPinsLeft); }\n            if n == 2 {\n                let first = self.rolls[start];\n                let second = self.rolls[start + 1];\n                if first == 10 && second < 10 && pins > 10 - second { return Err(Error::NotEnoughPinsLeft); }\n                if first != 10 && first + second < 10 { return Err(Error::GameComplete); }\n            }\n        } else if start < self.rolls.len() {\n            let frame_start = start;\n            if frame_start > 0 {\n                let prev = if frame_start >= 2 && self.rolls[frame_start - 2] != 10 { frame_start - 2 } else { frame_start - 1 };\n                if self.rolls[prev] != 10 && self.rolls[prev] + self.rolls[prev + 1] < 10 && frame_start == prev + 2 && self.rolls.len() == frame_start + 1 && pins > 10 - self.rolls[frame_start] { return Err(Error::NotEnoughPinsLeft); }\n            }\n        }\n        self.rolls.push(pins);\n        Ok(())\n    }\n\n    pub fn score(&self) -> Option<u16> {\n        if !self.complete() { return None; }\n        let mut score = 0;\n        let mut i = 0;\n        for _ in 0..10 {\n            if self.rolls[i] == 10 { score += 10 + self.rolls[i + 1] + self.rolls[i + 2]; i += 1; }\n            else if self.rolls[i] + self.rolls[i + 1] == 10 { score += 10 + self.rolls[i + 2]; i += 2; }\n            else { score += self.rolls[i] + self.rolls[i + 1]; i += 2; }\n        }\n        Some(score)\n    }\n}\n"}},
